WITH unpacked AS (SELECT id, customer_id, coupon_codes, attributes, ARRAY_CONTAINS(MAP_KEYS(attributes), 'gift') AS has_gift, ARRAY_MAX(TRANSFORM(items, item -> item.price)) AS max_item_price FROM carts) SELECT customer_id, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS num_rows, SUM(max_item_price) AS total_max_item_price, SUM(max_item_price) AS total_max_item_price_2 FROM unpacked GROUP BY customer_id HAVING SUM(max_item_price) > 0 ORDER BY total_max_item_price NULLS LAST;
